// Scanner state: which bracket we are inside, so `**` can be told apart —
// `f(**kw)` is fine and MicroPython supports it, `{**d}` is not.
#define PYGRAM_SYNTAX_DEPTH 24

static inline bool pygram_word_at(const char *s, const char *p, const char *word) {
    size_t n = strlen(word);
    if (strncmp(p, word, n) != 0) {
        return false;
    }
    // must not be part of a longer identifier on either side
    if (p > s && (isalnum((unsigned char)p[-1]) || p[-1] == '_')) {
        return false;
    }
    char after = p[n];
    return !(isalnum((unsigned char)after) || after == '_');
}

// Is `p` at the start of a logical line (only whitespace before it)?
static inline bool pygram_line_start(const char *s, const char *p) {
    while (p > s) {
        char c = *--p;
        if (c == '\n') {
            return true;
        }
        if (c != ' ' && c != '\t') {
            return false;
        }
    }
    return true;
}

// Does the line containing `p` end with a `:` (ignoring a trailing comment and
// trailing whitespace)? This is what separates the `match` STATEMENT from a
// variable called `match`, which is a common name and must not be flagged.
static inline bool pygram_line_ends_colon(const char *p) {
    char last = 0;
    bool in_s = false;
    char q = 0;
    for (; *p && *p != '\n'; p++) {
        if (in_s) {
            if (*p == '\\' && p[1]) {
                p++;
            } else if (*p == q) {
                in_s = false;
            }
            continue;
        }
        if (*p == '#') {
            break;
        }
        if (*p == '\'' || *p == '"') {
            in_s = true;
            q = *p;
            last = *p;
            continue;
        }
        if (*p != ' ' && *p != '\t' && *p != '\r') {
            last = *p;
        }
    }
    return last == ':';
}

/*
 * Return a description of the first construct in `src` that CPython accepts and
 * this parser does not, or NULL if none is present.
 *
 * Comments and string literals are skipped, so a docstring mentioning `match`
 * or a regex containing `{**` cannot trigger it.
 */
static inline const char *pygram_missing_syntax(const char *src) {
    if (src == NULL) {
        return NULL;
    }
    char stack[PYGRAM_SYNTAX_DEPTH];
    int depth = 0;
    bool in_class_header = false;
    int class_depth = 0;
    const char *p = src;
    while (*p) {
        char c = *p;
        // comment to end of line
        if (c == '#') {
            while (*p && *p != '\n') {
                p++;
            }
            continue;
        }
        // string literal, including the triple-quoted forms
        if (c == '\'' || c == '"') {
            char q = c;
            bool triple = (p[1] == q && p[2] == q);
            p += triple ? 3 : 1;
            while (*p) {
                if (*p == '\\' && p[1]) {
                    p += 2;
                    continue;
                }
                if (*p == q && (!triple || (p[1] == q && p[2] == q))) {
                    p += triple ? 3 : 1;
                    break;
                }
                p++;
            }
            continue;
        }
        if (c == '(' || c == '[' || c == '{') {
            if (depth < PYGRAM_SYNTAX_DEPTH) {
                stack[depth] = c;
            }
            depth++;
            p++;
            continue;
        }
        if (c == ')' || c == ']' || c == '}') {
            if (depth > 0) {
                depth--;
            }
            if (in_class_header && depth <= class_depth) {
                in_class_header = false;
            }
            p++;
            continue;
        }
        if (c == '\n') {
            if (depth == 0) {
                in_class_header = false;
            }
            p++;
            continue;
        }

        // `{**d}` — dict unpacking in a display. `f(**kw)` is supported, so the
        // innermost bracket has to be a brace for this to be the missing form.
        if (c == '*' && p[1] == '*' && depth > 0 && depth <= PYGRAM_SYNTAX_DEPTH
            && stack[depth - 1] == '{') {
            return "dict unpacking in a literal ({**d})";
        }

        // `def f(a, /, b)` — a positional-only marker. Only inside a paren, and
        // only when it stands alone between separators, so division is safe.
        if (c == '/' && depth > 0 && depth <= PYGRAM_SYNTAX_DEPTH && stack[depth - 1] == '(') {
            const char *b = p - 1;
            while (b > src && (*b == ' ' || *b == '\t')) {
                b--;
            }
            const char *a = p + 1;
            while (*a == ' ' || *a == '\t') {
                a++;
            }
            if ((*b == ',' || *b == '(') && (*a == ',' || *a == ')')) {
                return "positional-only parameter (def f(a, /, b))";
            }
        }

        if (isalpha((unsigned char)c) || c == '_') {
            if (pygram_word_at(src, p, "match") && pygram_line_start(src, p)
                && pygram_line_ends_colon(p)) {
                return "match statement";
            }
            if (pygram_word_at(src, p, "case") && pygram_line_start(src, p)
                && pygram_line_ends_colon(p)) {
                return "match statement (case clause)";
            }
            if (pygram_word_at(src, p, "except")) {
                const char *a = p + 6;
                while (*a == ' ' || *a == '\t') {
                    a++;
                }
                if (*a == '*') {
                    return "except* (exception groups)";
                }
            }
            if (pygram_word_at(src, p, "class") && pygram_line_start(src, p)) {
                in_class_header = true;
                class_depth = depth;
            }
            if (pygram_word_at(src, p, "with") && pygram_line_start(src, p)) {
                const char *a = p + 4;
                while (*a == ' ' || *a == '\t') {
                    a++;
                }
                if (*a == '(' && pygram_line_ends_colon(p)) {
                    return "parenthesized with-items";
                }
            }
            // step over the identifier so a name like `matching` is not
            // re-examined character by character
            while (isalnum((unsigned char)*p) || *p == '_') {
                p++;
            }
            continue;
        }

        // `class A(B, metaclass=M)` — a keyword in a class header.
        if (c == '=' && p[1] != '=' && (p == src || (p[-1] != '=' && p[-1] != '!'
                                                     && p[-1] != '<' && p[-1] != '>'))
            && in_class_header && depth == class_depth + 1) {
            return "keyword argument in a class header";
        }
        p++;
    }
    return NULL;
}
'''
