        && pygram_native_str_is_repr(self->subobj[0])) {
        mp_obj_t pygram_repr[2] = {MP_OBJ_NULL};
        struct class_lookup_data pygram_lookup = {
            .obj = self,
            .attr = MP_QSTR___repr__,
            .slot_offset = 0,
            .dest = pygram_repr,
            .is_type = false,
        };
        mp_obj_class_lookup(&pygram_lookup, self->base.type);
        if (pygram_repr[0] != MP_OBJ_NULL && pygram_repr[0] != MP_OBJ_SENTINEL) {
            member[0] = pygram_repr[0];
            member[1] = pygram_repr[1];
        }
